// stores/adapters/webAdapter.ts
import type { PlatformAdapter } from '../types'
import type { MessagePayload } from 'firebase/messaging'
import { messaging, getToken, onMessage } from '@/lib/firebase'
import { useAuthStore } from '@/store/auth'
import { useContactsStore } from '@/store/contacts'

// Web localStorage wrapper to match AsyncStorage API
const webStorage = {
  getItem: async (key: string) => {
    return localStorage.getItem(key)
  },
  setItem: async (key: string, value: string) => {
    localStorage.setItem(key, value)
  },
  removeItem: async (key: string) => {
    localStorage.removeItem(key)
  },
}

// Set up message listener (call this every page load)
const setupMessageListener = () => {
  onMessage(messaging, (payload: MessagePayload) => {
    console.log('Message received. ', payload)
    const title = payload?.notification?.title || 'Notification'
    const body = payload?.notification?.body || 'You have a new message'

    if (payload?.data?.type === 'friend_unavailable') {
      handleFriendUnavailable(payload.data)
      return
    }

    if (payload?.data?.type === 'friend_available') {
      handleFriendAvailable(payload.data)
      return
    }

    const notificationUrl =
      payload?.data?.type === 'incoming_call'
        ? `/calling?peerPhone=${encodeURIComponent(
            payload.data.caller_phone ||
              payload.data.phone ||
              payload.data.caller_id ||
              ''
          )}&callId=${encodeURIComponent(payload.data.call_id || payload.data.call_uuid || '')}`
        : '/some-route'

    if (Notification.permission === 'granted') {
      const notification = new Notification(title, {
        body: body,
        icon: '/buzzme.svg', // optional
        data: {
          url: notificationUrl,
        },
      })

      // Set click handler on the notification instance
      notification.onclick = (event) => {
        event.preventDefault() // Prevent default behavior (e.g. focusing tab)

        console.log(notification.data) // Correct way to access `data`

        window.focus() // Brings the tab to the front

        if (notification.data?.url) {
          window.location.href = notification.data.url // Redirect user
        }

        notification.close()
      }
    }
  })
}

const registerNotificationToken = async () => {
  try {
    // Register service worker (only needs to happen once, but safe to call multiple times)
    const registration = await navigator.serviceWorker.register(
      '/firebase-messaging-sw.js'
    )

    // registration.update()

    // Request permission
    const permission = await Notification.requestPermission()

    if (permission === 'granted') {
      // Get FCM token
      const vapidKey = import.meta.env.VITE_FIREBASE_VAPID_KEY

      const currentToken = await getToken(messaging, {
        vapidKey,
        serviceWorkerRegistration: registration,
      })

      if (currentToken) {
        console.log('FCM token:', currentToken)

        // Send token to backend
        await useAuthStore.getState().editUser({
          web_fcm_token: currentToken,
          device: 'web',
        })
      }
    }

    // Set up message listener
    setupMessageListener()
  } catch (error) {
    console.error('Failed to register web notification token:', error)
  }
}

export const webAdapter: PlatformAdapter = {
  getStorage: () => webStorage,
  showAlert: (title: string, message: string) => {
    alert(`${title}: ${message}`)
  },
  getTimezone: async () => {
    return Intl.DateTimeFormat().resolvedOptions().timeZone
  },
  clearStorage: async (key: string) => {
    localStorage.removeItem(key)
  },
  registerNotificationToken: registerNotificationToken,
  setupMessageListener,
}

