interface AuthStore {
  token: string | null
  user: User | null
  isLoading: boolean
  isUpdatingAvailability: boolean
  availabilityRequestId: number

  sendOtp: (phone: string) => Promise<void>
  getToken: (phone: string, otp: string) => Promise<boolean>
  getUser: (registerToken?: boolean, updateTimezone?: boolean) => Promise<void>
  getUserStatus: () => Promise<void>
