  toggleNotifications: () => Promise<void>
  setAvailability: (available: boolean, hours?: number) => Promise<boolean>
  deleteAccount: () => Promise<boolean>
  logout: () => Promise<boolean>

  // Computed properties
  isAuthenticated: () => boolean
  isOnboardingComplete: () => boolean
}

type AvailabilityStatusResponse = {
  success?: boolean
  data?: {
    is_available: boolean
    available_until?: number | null
    unavailable_until?: number | null
    status: string
    status_updated: boolean
  }
}

function requireAuth(
  get: () => AuthStore,
  withUser: true
): { token: string; user: User }
function requireAuth(
  get: () => AuthStore,
  withUser?: false
): { token: string }
function requireAuth(get: () => AuthStore, withUser: boolean = false) {
  if (!withUser) {
    const { token } = get()
    if (!token) {
      throw new Error('Authentication required')
    }

    return { token }
  } else {
    const { token, user } = get()
    if (!token || !user) {
      throw new Error('Authentication required')
    }

    return { token, user }
  }
}

