@router.post("/edit_user")
async def edit_user(data: EditUserRequest, user: CurrentUser) -> dict:
    if data.phone is not None:
        user.phone = data.phone
    if data.onboarding_step is not None:
        user.onboarding_step = data.onboarding_step
    if data.fcm_token is not None:
        user.fcm_token = data.fcm_token
    if data.web_fcm_token is not None:
