@router.post("/delete_account_with_token")
async def delete_account_with_token(data: DeleteAccountRequest, session: SessionDep) -> dict:
    if not data.confirm:
        raise HTTPException(
            status_code=400,
            detail="Account deletion must be confirmed by setting 'confirm' to true",
