import { AppState, Platform } from 'react-native'

type DebugDetails = Record<string, unknown>

const LOG_PREFIX = '[CALL_DEBUG]'
const MAX_STRING_LENGTH = 500

function redactToken(value: unknown) {
  if (typeof value !== 'string') return value
  if (value.length <= 14) return `[redacted:${value.length}]`
  return `${value.slice(0, 6)}...${value.slice(-4)} (${value.length})`
}

function safeValue(key: string, value: unknown): unknown {
  if (value instanceof Error) {
    return {
      name: value.name,
      message: value.message,
      stack: value.stack?.split('\n').slice(0, 4).join('\n'),
    }
  }

  if (/token/i.test(key)) {
    return redactToken(value)
  }

  if (typeof value === 'string') {
    return value.length > MAX_STRING_LENGTH
      ? `${value.slice(0, MAX_STRING_LENGTH)}...(${value.length})`
      : value
  }

  if (Array.isArray(value)) {
    return value.map((item, index) => safeValue(String(index), item))
  }

  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([childKey, childValue]) => [
        childKey,
        safeValue(childKey, childValue),
      ])
    )
  }

  return value
}

function safeDetails(details: DebugDetails = {}) {
  return Object.fromEntries(
    Object.entries(details)
      .filter(([, value]) => value !== undefined)
      .map(([key, value]) => [key, safeValue(key, value)])
  )
}

function write(level: 'log' | 'warn' | 'error', event: string, details?: DebugDetails) {
  const payload = {
    event,
    ts: new Date().toISOString(),
    platform: Platform.OS,
    appState: AppState.currentState,
    ...safeDetails(details),
  }

  console[level](LOG_PREFIX, JSON.stringify(payload))
}

export function logCallDebug(event: string, details?: DebugDetails) {
  write('log', event, details)
}

export function logCallWarn(event: string, details?: DebugDetails) {
  write('warn', event, details)
}

export function logCallError(event: string, error: unknown, details?: DebugDetails) {
  write('error', event, { ...details, error })
}

export function summarizeWsMessage(message: Record<string, unknown>) {
  return {
    type: message.type,
    from: message.from,
    to: message.to,
    callId: message.callId || message.call_id || message.call_uuid,
    hasOffer: !!message.offer,
    hasAnswer: !!message.answer,
    hasCandidate: !!message.candidate,
    muted: message.muted,
    isAvailable: message.is_available,
  }
}

