    // CASE 1: Handle call notification action buttons (accept/decline)
    if (type === EventType.ACTION_PRESS && notification?.data?.call) {
      // Legacy call action handling — currently a no-op.
      logCallDebug('NOTIFEE_EVENT_LEGACY_CALL_ACTION', {
        notificationId: notification?.id,
        pressActionId: pressAction?.id,
        data: notification.data,
      })
