  Notifee.onBackgroundEvent(onNotificationAction)
  Notifee.onForegroundEvent(onNotificationAction)
  logCallDebug('NOTIFEE_EVENT_HANDLERS_REGISTERED')
}

// Display ongoing call notification
export const displayOngoingCallNotification = async (
  callId,
  callerName = 'NAME HERE',
  isVideo = false
) => {
  logCallDebug('ONGOING_CALL_NOTIFICATION_START', {
    callId,
    callerName,
    isVideo,
  })
  const options = {
    taskName: 'Call',
    taskTitle: `Ongoing call with ${callerName}`,
    taskDesc: isVideo ? 'Video call in progress' : 'Voice call in progress',
    taskIcon: {
      name: 'ic_launcher',
      type: 'mipmap',
    },
    color: '#000000',
    linkingURI: `zing://calling-screen`,
    parameters: {
      delay: 1000,
      callId: callId,
      callerName: callerName,
      isVideo: isVideo,
    },
  }

  try {
    // Check if service is already running and stop it first
    if (await BackgroundService.isRunning()) {
      logCallDebug('ONGOING_CALL_NOTIFICATION_STOP_EXISTING', { callId })
      await BackgroundService.stop()
    }

    // Proper background task implementation
    const ongoingCallTask = async taskDataArguments => {
      const { delay } = taskDataArguments

      // This is the correct pattern according to the documentation
      await new Promise(async resolve => {
        // Keep running while the service is active
        while (BackgroundService.isRunning()) {
          logCallDebug('ONGOING_CALL_NOTIFICATION_TICK', { callId, callerName })
          await sleep(delay || 1000)
        }
        resolve()
      })
    }

    await BackgroundService.start(ongoingCallTask, options)
    logCallDebug('ONGOING_CALL_NOTIFICATION_STARTED', { callId })

    // Update notification description
    await BackgroundService.updateNotification({
      taskDesc: isVideo ? 'Video call in progress' : 'Voice call in progress',
    })
  } catch (error) {
    logCallError('ONGOING_CALL_NOTIFICATION_START_ERROR', error, { callId })
  }
}

export const hideOngoingCallNotification = async call => {
  logCallDebug('ONGOING_CALL_NOTIFICATION_HIDE_START', { call })

  try {
    // Check if the service is running
    const isRunning = await BackgroundService.isRunning()
    logCallDebug('ONGOING_CALL_NOTIFICATION_RUNNING_STATUS', { call, isRunning })

    if (isRunning) {
      await BackgroundService.stop()
      logCallDebug('ONGOING_CALL_NOTIFICATION_STOPPED', { call })

      // Verify it stopped
      const isStillRunning = await BackgroundService.isRunning()
      logCallDebug('ONGOING_CALL_NOTIFICATION_STOP_VERIFY', { call, isStillRunning })
    } else {
      logCallDebug('ONGOING_CALL_NOTIFICATION_NOT_RUNNING', { call })
    }
  } catch (error) {
    logCallError('ONGOING_CALL_NOTIFICATION_HIDE_ERROR', error, { call })
  }
}

