          const pc = get().pc
          if (pc) {
            logCallStore('WS_ANSWER_HANDLE_START', { from: msg.from, callId: msg.callId })
            await pc.setRemoteDescription(new RTCSessionDescription(msg.answer))
            await flushPendingCandidates(pc)
            set({ state: 'in-call' })
            InCallManager.stopRingback()
            logCallStore('WS_ANSWER_HANDLE_SUCCESS', { from: msg.from, callId: msg.callId })
          } else {
            logCallWarn('WS_ANSWER_WITHOUT_PC', { ...callSnapshot(), from: msg.from })
          }
          break
        }

        case 'candidate': {
          const pc = get().pc
          // Only add a candidate once the remote description is set, otherwise
          // buffer it. This covers both the callee before acceptCall (no pc
          // yet) and the caller before the answer arrives (pc exists but has no
          // remote description yet) — adding too early throws and drops it.
          if (pc && pc.remoteDescription && msg.candidate) {
            try {
              await pc.addIceCandidate(new RTCIceCandidate(msg.candidate))
              logCallStore('WS_ICE_CANDIDATE_ADDED', { from: msg.from, callId: msg.callId })
            } catch (error) {
              logCallError('WS_ICE_CANDIDATE_ADD_ERROR', error, {
                ...callSnapshot(),
                from: msg.from,
                callId: msg.callId,
              })
            }
          } else if (msg.candidate) {
            pendingIceCandidates.push(msg.candidate)
            logCallStore('WS_ICE_CANDIDATE_BUFFERED', {
              from: msg.from,
              callId: msg.callId,
              pendingIceCount: pendingIceCandidates.length,
              hasPc: !!pc,
              hasRemoteDescription: !!pc?.remoteDescription,
            })
          }
          break
        }

        case 'end':
          logCallStore('WS_END_RECEIVED', { from: msg.from, callId: msg.callId })
          set({ state: 'ended' })
          closeConnection()
          // Navigate back using Expo Router
          if (router.canGoBack()) {
            router.back()
          } else {
            router.replace('/')
          }
          break

        case 'mic-status':
          // Optional: update remote mic status in UI
          logCallStore('WS_MIC_STATUS_RECEIVED', { from: msg.from, muted: msg.muted })
          break

        case 'self_availability_update':
          logCallStore('WS_SELF_AVAILABILITY_UPDATE', { isAvailable: msg.is_available })
          useAuthStore.setState(state => ({
            user: state.user
              ? {
                  ...state.user,
                  is_available: msg.is_available,
                }
              : null,
          }))
          break

        case 'registered':
          logCallStore('WS_REGISTERED_ACK', { id: msg.id })
          break

        default:
          logCallWarn('WS_UNKNOWN_MESSAGE_TYPE', summarizeWsMessage(msg))
          break
      }
    }

    ws.onclose = () => {
      logCallStore('WS_CLOSED')
      tryReconnect()
    }

    ws.onerror = error => {
      logCallError('WS_ERROR', error, callSnapshot())
      ws.close()
    }

    set({ ws })
    logCallStore('WS_INSTANCE_STORED')
  }

  function tryReconnect() {
    if (reconnectAttempts > 5) {
      logCallWarn('WS_RECONNECT_MAX_ATTEMPTS_REACHED', { reconnectAttempts })
      return
    }
    reconnectAttempts++
    logCallStore('WS_RECONNECT_SCHEDULED', {
      reconnectAttempts,
      delayMs: 1000 * reconnectAttempts,
    })
    setTimeout(() => setupWebSocket(), 1000 * reconnectAttempts)
  }

  async function setupPeerConnection() {
    logCallStore('PC_SETUP_START', {
      iceServerCount: iceServers.iceServers.length,
      hasTurn: !!process.env.EXPO_PUBLIC_TURN_URL,
    })
    const pc = new RTCPeerConnection(iceServers)
    const ws = get().ws
    const targetId = get().targetId!
    const { videoEnabled } = get()

    try {
      logCallStore('MEDIA_GET_USER_MEDIA_START', { audio: true, video: videoEnabled })
      const localStream = await mediaDevices.getUserMedia({
        audio: true,
        video: videoEnabled,
      })
      logCallStore('MEDIA_GET_USER_MEDIA_SUCCESS', {
        audioTrackCount: localStream.getAudioTracks().length,
        videoTrackCount: localStream.getVideoTracks().length,
      })

      // Apply video effects if mask is enabled
      await applyVideoEffects(localStream)
      logCallStore('MEDIA_VIDEO_EFFECTS_APPLIED', {
        videoTrackCount: localStream.getVideoTracks().length,
      })

      localStream.getTracks().forEach(track => {
        pc.addTrack(track, localStream)
      })
      logCallStore('PC_LOCAL_TRACKS_ADDED', {
        trackCount: localStream.getTracks().length,
        audioTrackCount: localStream.getAudioTracks().length,
        videoTrackCount: localStream.getVideoTracks().length,
      })

      pc.ontrack = event => {
        logCallStore('PC_REMOTE_TRACK_RECEIVED', {
          streamCount: event.streams.length,
          trackKind: event.track?.kind,
        })
        set({ remoteStream: event.streams[0] })
      }

      pc.onconnectionstatechange = () => {
        logCallStore('PC_CONNECTION_STATE_CHANGE', {
          connectionState: pc.connectionState,
          iceConnectionState: pc.iceConnectionState,
          signalingState: pc.signalingState,
        })
        if (['disconnected', 'failed', 'closed'].includes(pc.connectionState)) {
          closeConnection()
        } else if (pc.connectionState === 'connected') {
          set({ state: 'in-call' })
          logCallStore('PC_CONNECTED_STATE_IN_CALL')
        }
      }

      // Trickle ICE: forward each local candidate to the peer as it's gathered
      pc.onicecandidate = event => {
        if (!event.candidate) {
          logCallStore('PC_ICE_GATHERING_COMPLETE')
          return
        }
        const { ws, targetId, currentCallId } = get()
        if (ws?.readyState === WebSocket.OPEN && targetId) {
          ws.send(
            JSON.stringify({
              type: 'candidate',
              to: targetId,
              callId: currentCallId,
              candidate: event.candidate,
            })
          )
          logCallStore('PC_ICE_CANDIDATE_SENT', {
            to: targetId,
            callId: currentCallId,
            candidateType: event.candidate.type,
            sdpMid: event.candidate.sdpMid,
            sdpMLineIndex: event.candidate.sdpMLineIndex,
          })
        } else {
          logCallWarn('PC_ICE_CANDIDATE_NOT_SENT_WS_UNAVAILABLE', {
            ...callSnapshot(),
            candidateType: event.candidate.type,
          })
        }
      }

      // Renegotiate when the set of tracks changes after the call is up (e.g.
      // video enabled mid-call). The first offer/answer is driven manually by
      // callUser/acceptCall, so we only auto-renegotiate once we're in-call.
      pc.onnegotiationneeded = async () => {
        if (get().state !== 'in-call') {
          logCallStore('PC_NEGOTIATION_NEEDED_IGNORED', { state: get().state })
          return
        }
        try {
          logCallStore('PC_RENEGOTIATION_START')
          const offer = await pc.createOffer()
          await pc.setLocalDescription(offer)
          const { ws, targetId, currentCallId } = get()
          if (ws?.readyState === WebSocket.OPEN && targetId) {
            ws.send(
              JSON.stringify({ type: 'offer', to: targetId, callId: currentCallId, offer })
            )
            logCallStore('PC_RENEGOTIATION_OFFER_SENT', { to: targetId, callId: currentCallId })
          } else {
            logCallWarn('PC_RENEGOTIATION_OFFER_NOT_SENT_WS_UNAVAILABLE', callSnapshot())
          }
        } catch (error) {
          logCallError('PC_RENEGOTIATION_ERROR', error, callSnapshot())
        }
      }

      set({ pc, localStream })
      logCallStore('PC_SETUP_SUCCESS')
      return pc
    } catch (error) {
      logCallError('PC_SETUP_ERROR', error, callSnapshot())
      throw error
    }
  }

  async function callUser(targetId: string, callUUID: string) {
    const { callInProgress } = get()
    logCallStore('CALL_USER_START', { targetId, callId: callUUID })

    // Prevent multiple call initiations
    if (callInProgress) {
      logCallWarn('CALL_USER_IGNORED_ALREADY_IN_PROGRESS', {
        ...callSnapshot(),
        requestedTargetId: targetId,
        requestedCallId: callUUID,
      })
      return
    }

    InCallManager.start({ media: 'audio', auto: true, ringback: '_DEFAULT_' })
    logCallStore('CALL_USER_RINGBACK_START', { targetId, callId: callUUID })
    try {
      const callId = callUUID
      set({ targetId, state: 'calling', currentCallId: callId, callInProgress: true })
      logCallStore('CALL_USER_STATE_SET_CALLING', { targetId, callId })

      const contact = useContactsStore
        .getState()
        .contacts.find(contact => contact.phone === targetId)
      if (Platform.OS === 'ios') {
        RNCallKeep.startCall(callId, targetId, contact?.name || targetId)
        logCallStore('CALL_USER_IOS_CALLKEEP_START_CALL', {
          targetId,
          callId,
          displayName: contact?.name || targetId,
        })
      }

      const pc = await setupPeerConnection()
      logCallStore('CALL_USER_CREATE_OFFER_START', { targetId, callId })
      const offer = await pc.createOffer()
      await pc.setLocalDescription(offer)
      logCallStore('CALL_USER_LOCAL_DESCRIPTION_SET', {
        targetId,
        callId,
        offerType: offer.type,
      })

      const ws = get().ws
      if (ws?.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ type: 'offer', to: targetId, callId, offer }))
        logCallStore('CALL_USER_OFFER_SENT', { targetId, callId })
      } else {
        logCallWarn('CALL_USER_OFFER_NOT_SENT_WS_UNAVAILABLE', callSnapshot())
      }
    } catch (error) {
      logCallError('CALL_USER_ERROR', error, { ...callSnapshot(), targetId, callId: callUUID })
      closeConnection()
    }
  }

  // Apply any ICE candidates that were buffered before the remote description
  // was set, then clear the buffer.
  async function flushPendingCandidates(pc: RTCPeerConnection) {
    if (pendingIceCandidates.length === 0) return
    const buffered = pendingIceCandidates
    pendingIceCandidates = []
    logCallStore('ICE_BUFFER_FLUSH_START', { count: buffered.length })
    for (const candidate of buffered) {
      try {
        await pc.addIceCandidate(new RTCIceCandidate(candidate))
        logCallStore('ICE_BUFFER_CANDIDATE_ADDED')
      } catch (error) {
        logCallError('ICE_BUFFER_CANDIDATE_ADD_ERROR', error, callSnapshot())
      }
    }
    logCallStore('ICE_BUFFER_FLUSH_COMPLETE', { count: buffered.length })
  }

  // Resolve once the WS-relayed offer has arrived (or null on timeout). When
  // answering from a CallKit/notification cold-start, the offer is replayed by
  // the server a moment after we register on the socket, so acceptCall must
  // wait for it rather than assume it's already here.
  function waitForIncomingOffer(timeoutMs = 10000): Promise<RTCSessionDescriptionInit | null> {
    if (incomingOffer) {
      logCallStore('WAIT_FOR_OFFER_ALREADY_AVAILABLE')
      return Promise.resolve(incomingOffer)
    }
    logCallStore('WAIT_FOR_OFFER_START', { timeoutMs })
    return new Promise(resolve => {
      const start = Date.now()
      const interval = setInterval(() => {
        if (incomingOffer) {
          clearInterval(interval)
          logCallStore('WAIT_FOR_OFFER_SUCCESS', { elapsedMs: Date.now() - start })
          resolve(incomingOffer)
        } else if (Date.now() - start > timeoutMs) {
          clearInterval(interval)
          logCallWarn('WAIT_FOR_OFFER_TIMEOUT', { ...callSnapshot(), timeoutMs })
          resolve(null)
        }
      }, 100)
    })
  }

  async function acceptCall() {
    logCallStore('ACCEPT_CALL_START')
    InCallManager.stopRingtone()
    InCallManager.start()
    set({ callInProgress: true })
    logCallStore('ACCEPT_CALL_AUDIO_STARTED')
    try {
      if (!incomingOffer) {
      if (!incomingOffer) {
        incomingOffer = await waitForIncomingOffer()
      }
      if (!incomingOffer) {
        logCallWarn('ACCEPT_CALL_NO_OFFER_REJECTING', callSnapshot())
        rejectCall()
        return
      }

      const pc = await setupPeerConnection()
      await pc.setRemoteDescription(new RTCSessionDescription(incomingOffer))
      logCallStore('ACCEPT_CALL_REMOTE_DESCRIPTION_SET')
      await flushPendingCandidates(pc)

      const answer = await pc.createAnswer()
      await pc.setLocalDescription(answer)
      logCallStore('ACCEPT_CALL_LOCAL_DESCRIPTION_SET', { answerType: answer.type })

      const { ws, targetId, currentCallId } = get()
      if (ws?.readyState === WebSocket.OPEN) {
        ws.send(
          JSON.stringify({
            type: 'answer',
            to: targetId,
            answer,
            callId: currentCallId,
          })
        )
        logCallStore('ACCEPT_CALL_ANSWER_SENT', { targetId, callId: currentCallId })
      } else {
        logCallWarn('ACCEPT_CALL_ANSWER_NOT_SENT_WS_UNAVAILABLE', callSnapshot())
      }

      set({ state: 'in-call' })
      incomingOffer = null
      logCallStore('ACCEPT_CALL_SUCCESS')
    } catch (error) {
      logCallError('ACCEPT_CALL_ERROR', error, callSnapshot())
      incomingOffer = null
      pendingIceCandidates = []
      rejectCall()
    }
  }

  // 2. Fix rejectCall - same pattern
  function rejectCall() {
    logCallStore('REJECT_CALL_START')
    InCallManager.stopRingtone()
    InCallManager.stop()

    // Get fresh state instead of using closure
    const { ws, targetId, currentCallId } = get()

    if (currentCallId && Platform.OS === 'ios') {
      RNCallKeep.rejectCall(currentCallId)
      logCallStore('REJECT_CALL_IOS_CALLKEEP_REJECT', { callId: currentCallId })
    }

    if (ws?.readyState === WebSocket.OPEN && targetId) {
      ws.send(
        JSON.stringify({
          type: 'end',
          to: targetId,
          callId: currentCallId,
        })
      )
      logCallStore('REJECT_CALL_WS_END_SENT', { targetId, callId: currentCallId })
    } else {
      logCallWarn('REJECT_CALL_WS_END_NOT_SENT', callSnapshot())
    }

    incomingOffer = null // Clear it
    closeConnection()
  }

  function endCall() {
    const ws = get().ws
    const currentCallId = get().currentCallId
    const currentState = get().state
    logCallStore('END_CALL_START', { currentState })

    // End the CallKit call on iOS (Android uses the notification module)
    if (currentCallId && Platform.OS === 'ios') {
      RNCallKeep.endCall(currentCallId)
      logCallStore('END_CALL_IOS_CALLKEEP_END', { callId: currentCallId })
    }

    // If it's an outgoing call that hasn't been accepted yet, send cancel notification
    if (currentState === 'calling') {
      // Call the API to send cancel notification instead of WebSocket
      const targetId = get().targetId
      if (targetId && currentCallId) {
        logCallStore('END_CALL_CANCEL_API_START', { targetId, callId: currentCallId })
        apiCancelCall(targetId, currentCallId)
      }

      if (ws?.readyState === WebSocket.OPEN) {
        ws.send(
          JSON.stringify({
            type: 'end',
            to: get().targetId,
            callId: get().currentCallId,
          })
        )
        logCallStore('END_CALL_CALLING_WS_END_SENT', {
          targetId: get().targetId,
          callId: get().currentCallId,
        })
      } else {
        logCallWarn('END_CALL_CALLING_WS_END_NOT_SENT', callSnapshot())
      }
    } else {
      // For accepted calls, use WebSocket to end the call
      if (ws?.readyState === WebSocket.OPEN) {
        ws.send(
          JSON.stringify({
            type: 'end',
            to: get().targetId,
            callId: get().currentCallId,
          })
        )
        logCallStore('END_CALL_ACTIVE_WS_END_SENT', {
          targetId: get().targetId,
          callId: get().currentCallId,
        })
      } else {
        logCallWarn('END_CALL_ACTIVE_WS_END_NOT_SENT', callSnapshot())
      }
    }

    set({ state: 'ended' })
    logCallStore('END_CALL_STATE_ENDED')
    closeConnection()
  }

  function closeConnection() {
    const { pc, localStream, currentCallId } = get()
    logCallStore('CLOSE_CONNECTION_START')

    if (currentCallId && Platform.OS === 'ios') {
      RNCallKeep.reportEndCallWithUUID(currentCallId, 2) // 2 = Remote user ended call
      logCallStore('CLOSE_CONNECTION_IOS_REPORT_END', { callId: currentCallId })
    }

    // Close peer connection
    if (pc) {
      pc.close()
      logCallStore('CLOSE_CONNECTION_PC_CLOSED')
    }

    // Stop all tracks
    if (localStream) {
      logCallStore('CLOSE_CONNECTION_STOP_TRACKS', {
        trackCount: localStream.getTracks().length,
      })
      localStream.getTracks().forEach(track => {
        track.stop()
      })
    }

    // Reset state
    InCallManager.stop()
    set({
      pc: null,
      localStream: null,
      remoteStream: null,
      state: 'idle',
      targetId: null,
      currentCallId: null,
      muted: false,
      videoEnabled: false,
      callInProgress: false,
    })

    incomingOffer = null
    pendingIceCandidates = [] // Clear pending candidates
    logCallStore('CLOSE_CONNECTION_COMPLETE')
  }

  function toggleMute(mute: boolean) {
    const { localStream, ws, targetId, currentCallId } = get()
    logCallStore('TOGGLE_MUTE_START', { mute })

    if (localStream) {
      localStream.getAudioTracks().forEach(track => {
        track.enabled = !mute
      })
      logCallStore('TOGGLE_MUTE_LOCAL_TRACKS_UPDATED', {
        mute,
        audioTrackCount: localStream.getAudioTracks().length,
      })
    }

    // Use platform-agnostic interface to set mute state
    if (currentCallId) {
      callPlatform.setMuted(currentCallId, mute)
    }

    set({ muted: mute })

    // Notify remote peer
    if (ws?.readyState === WebSocket.OPEN && targetId) {
      ws.send(
        JSON.stringify({
          type: 'mic-status',
          to: targetId,
          muted: mute,
        })
      )
      logCallStore('TOGGLE_MUTE_WS_SENT', { targetId, muted: mute })
    } else {
      logCallWarn('TOGGLE_MUTE_WS_NOT_SENT', callSnapshot())
    }
  }

