export const setMuted = (callId: string, muted: boolean): void => {
  logCallDebug('IOS_CALLKEEP_SET_MUTED', { callId, muted })
  try {
    RNCallKeep.setMutedCall(callId, muted)
  } catch (e) {
    logCallError('IOS_CALLKEEP_SET_MUTED_ERROR', e, { callId, muted })
  }
}

// Register iOS CallKeep event listeners
export const registerEventListeners = (): void => {
  logCallDebug('IOS_CALLKEEP_EVENT_LISTENERS_REGISTER')
  // Answer call event
  RNCallKeep.addEventListener('answerCall', async ({ callUUID }: { callUUID: string }) => {
    logCallDebug('IOS_CALLKEEP_ANSWER_EVENT', { callId: callUUID })
    const { acceptCall, init, wsInitTriggered } = useCallsStore.getState()

    // Ensure the signaling socket is up. acceptCall() internally waits for the
    // server-replayed offer before building the answer, so this is safe even on
    // a cold start where the offer hasn't arrived yet.
    if (!wsInitTriggered) {
      logCallDebug('IOS_CALLKEEP_ANSWER_EVENT_INIT_WS', { callId: callUUID })
      init()
    }
    acceptCall()
    logCallDebug('IOS_CALLKEEP_ANSWER_EVENT_ACCEPT_CALLED', { callId: callUUID })
    RNCallKeep.backToForeground()
    logCallDebug('IOS_CALLKEEP_ANSWER_EVENT_BACK_TO_FOREGROUND', { callId: callUUID })
  })

  // End call event
  RNCallKeep.addEventListener('endCall', async ({ callUUID }: { callUUID: string }) => {
    logCallDebug('IOS_CALLKEEP_END_EVENT', { callId: callUUID })
    const { rejectCall, endCall, state, targetId } = useCallsStore.getState()

    if (state === 'in-call') {
      // User is ending an active call
      logCallDebug('IOS_CALLKEEP_END_EVENT_ACTIVE_CALL', { callId: callUUID, state })
      endCall()
    } else {
      // User is rejecting an incoming call
      logCallDebug('IOS_CALLKEEP_END_EVENT_REJECT_INCOMING', {
        callId: callUUID,
        state,
        targetId,
      })
      rejectCall()

      // Notify caller about rejection
      if (targetId) {
        logCallDebug('IOS_CALLKEEP_END_EVENT_API_REJECT_START', {
          callId: callUUID,
          targetId,
        })
        apiRejectCall(targetId)
      }
    }
  })

  // Mute event
  RNCallKeep.addEventListener(
    'didPerformSetMutedCallAction',
    ({ muted, callUUID }: { muted: boolean; callUUID: string }) => {
    logCallDebug('IOS_CALLKEEP_MUTE_EVENT', { callId: callUUID, muted })
    const { toggleMute } = useCallsStore.getState()
    toggleMute(muted)
    }
  )
}

// Clean up listeners
export const cleanupEventListeners = (): void => {
  logCallDebug('IOS_CALLKEEP_EVENT_LISTENERS_CLEANUP')
  RNCallKeep.removeEventListener('answerCall')
  RNCallKeep.removeEventListener('endCall')
  RNCallKeep.removeEventListener('didPerformSetMutedCallAction')
}

